// Loop over input items and add a new field called 'myNewField' to the JSON of each one
const rows = $input.all();

return rows.map(item => {
  const impressions = Number(item.json.impressions || 0);
  const reactions = Number(item.json.reactions || 0);
  const comments = Number(item.json.comments || 0);
  const reposts = Number(item.json.reposts || 0);

  const totalEngagement = reactions + comments + reposts;

  const engagementRate = impressions > 0
    ? (totalEngagement / impressions) * 100
    : 0;

  return {
    json: {
      ...item.json,
      engagement_rate: Number(engagementRate.toFixed(2))
    }
  };
});

// Build a weekly LinkedIn summary from all rows
const rows = $input.all().map(item => item.json);

// Today's date in India timezone (YYYY-MM-DD)
const today = new Intl.DateTimeFormat('en-CA', {
  timeZone: 'Asia/Kolkata',
  year: 'numeric',
  month: '2-digit',
  day: '2-digit'
}).format(new Date());

// Convert date to UTC day number for reliable comparison
const todayDate = new Date(today + 'T00:00:00Z');
const todayDay = Math.floor(todayDate.getTime() / 86400000);

// Last 7 calendar days, including today
const startDay = todayDay - 6;

function parseDate(value) {
  if (!value) return null;

  const text = String(value).trim();

  // Google Sheets date format: MM/DD/YYYY
  const usDate = text.match(/^(\d{1,2})\/(\d{1,2})\/(\d{4})$/);
  if (usDate) {
    const [, month, day, year] = usDate;
    return Date.UTC(Number(year), Number(month) - 1, Number(day)) / 86400000;
  }

  // ISO date format: YYYY-MM-DD
  const isoDate = text.match(/^(\d{4})-(\d{2})-(\d{2})/);
  if (isoDate) {
    const [, year, month, day] = isoDate;
    return Date.UTC(Number(year), Number(month) - 1, Number(day)) / 86400000;
  }

  return null;
}

function formatDay(dayNumber) {
  return new Date(dayNumber * 86400000).toISOString().slice(0, 10);
}

// Keep only posts from the last 7 days
const weeklyPosts = rows.filter(row => {
  const day = parseDate(row.post_date);
  return day !== null && day >= startDay && day <= todayDay;
});

let totalImpressions = 0;
let totalReactions = 0;
let totalComments = 0;
let totalReposts = 0;
let rateSum = 0;
let bestPost = null;

for (const post of weeklyPosts) {
  const rate = Number(post.engagement_rate || 0);
  totalImpressions += Number(post.impressions || 0);
  totalReactions += Number(post.reactions || 0);
  totalComments += Number(post.comments || 0);
  totalReposts += Number(post.reposts || 0);
  rateSum += rate;

  if (!bestPost || rate > Number(bestPost.engagement_rate || 0)) {
    bestPost = post;
  }
}

const totalPosts = weeklyPosts.length;
const averageRate = totalPosts > 0 ? rateSum / totalPosts : 0;

return [
  {
    json: {
      report_period: formatDay(startDay) + ' to ' + formatDay(todayDay),
      total_posts: totalPosts,
      total_impressions: totalImpressions,
      total_reactions: totalReactions,
      total_comments: totalComments,
      total_reposts: totalReposts,
      average_engagement_rate: Number(averageRate.toFixed(2)),
      best_performing_post: bestPost
        ? (bestPost.post_topic || 'Untitled') + ' (' + (bestPost.topic_id || '') + ')'
        : 'No posts in this period',
      best_post_engagement_rate: bestPost ? Number(Number(bestPost.engagement_rate || 0).toFixed(2)) : 0
    }
  }
];
